415	    /**
416	     * Rolls a registration date forward to a business day: a Saturday or Sunday is advanced to the
417	     * following Monday, any weekday is returned unchanged.
418	     *
419	     * @param date the effective registration date, supplied or defaulted to the server date
420	     * @return the same date when it is a weekday, otherwise the next Monday
421	     */
422	    private static LocalDate toBusinessDay(LocalDate date) {
423	        DayOfWeek dayOfWeek = date.getDayOfWeek();
424	        if (dayOfWeek == DayOfWeek.SATURDAY) {
425	            return date.plusDays(2);
426	        }
427	        if (dayOfWeek == DayOfWeek.SUNDAY) {
428	            return date.plusDays(1);
429	        }
430	        return date;
431	    }
