433	    /**
434	     * Builds the customer code assigned to an owner on create, formatted {@code '<REGION>-<HASH8>'}
435	     * where {@code REGION} is the region code derived from the owner's postcode (the region whose
436	     * inclusive range contains the postcode, or {@code 'UNKNOWN'} when the postcode is absent or in
437	     * no known range) and {@code HASH8} is the first eight upper-cased hex characters of the SHA-256
438	     * of {@code normalizedTelephone + lastName}, e.g. {@code 'NSW-1A2B3C4D'}. There is no sequence
439	     * component: the identity is a pure region-and-hash value.
440	     *
441	     * @param postcode the postcode of the owner being created, may be {@code null}
442	     * @param normalizedTelephone the E.164 telephone of the owner being created
443	     * @param lastName the last name of the owner being created
444	     * @return the formatted customer code
445	     */
446	    private String customerCode(String postcode, String normalizedTelephone, String lastName) {
447	        return regionFromPostcode(postcode) + "-" + sha256HexPrefix(normalizedTelephone + lastName, 8);
448	    }
449	
450	    /**
451	     * Returns the region code whose inclusive postcode range contains the given 4-digit postcode
452	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), or {@code 'UNKNOWN'} when the postcode is
453	     * {@code null}, non-numeric, or in no known range.
454	     *
455	     * @param postcode the postcode, may be {@code null}
456	     * @return the region code, or {@code 'UNKNOWN'}
457	     */
458	    private static String regionFromPostcode(String postcode) {
459	        if (postcode == null || postcode.isBlank()) {
460	            return "UNKNOWN";
461	        }
462	        int code;
463	        try {
464	            code = Integer.parseInt(postcode.trim());
465	        } catch (NumberFormatException e) {
466	            return "UNKNOWN";
467	        }
468	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
469	            int[] range = entry.getValue();
470	            if (code >= range[0] && code <= range[1]) {
471	                return entry.getKey();
472	            }
473	        }
474	        return "UNKNOWN";
475	    }
476	
477	    /**
478	     * Computes the SHA-256 of {@code value} and returns its first {@code length} hex characters,
479	     * upper-cased.
480	     *
481	     * @param value the string to hash
482	     * @param length the number of leading hex characters to return
483	     * @return the upper-cased hex prefix of the digest
484	     */
485	    private static String sha256HexPrefix(String value, int length) {
486	        try {
487	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
488	            StringBuilder sb = new StringBuilder(digest.length * 2);
489	            for (byte b : digest) {
490	                sb.append(String.format("%02x", b));
491	            }
492	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
493	        } catch (NoSuchAlgorithmException e) {
494	            throw new IllegalStateException("SHA-256 not available", e);
495	        }
496	    }
