498	    /**
499	     * Counts the existing owners that share the owner-to-be's first and last name, compared
500	     * case-insensitively (surrounding whitespace trimmed). The count reflects the state before the
501	     * new owner is persisted, so it excludes the owner being created.
502	     *
503	     * @param firstName the first name of the owner being created
504	     * @param lastName the last name of the owner being created
505	     * @return the number of existing owners with the same first and last name
506	     */
507	    private int countNamesakes(String firstName, String lastName) {
508	        String normalizedFirstName = normalizeName(firstName);
509	        String normalizedLastName = normalizeName(lastName);
510	        return (int) this.clinicService.findAllOwners().stream()
511	            .filter(existing ->
512	                normalizedFirstName.equals(normalizeName(existing.getFirstName()))
513	                    && normalizedLastName.equals(normalizeName(existing.getLastName())))
514	            .count();
515	    }
516	
517	    /**
518	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
519	     * number of existing owners already carrying the same {@code householdId}. A household identifier
520	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
521	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
522	     * count includes the owner being created (hence the {@code + 1}).
523	     *
524	     * @param householdId the stable household identifier of the owner being created, or {@code null}
525	     *     when the owner does not share a household
526	     * @return the number of household members after this create (always at least 1)
527	     */
528	    private int householdSize(String householdId) {
529	        if (householdId == null) {
530	            return 1;
531	        }
532	        return (int) this.clinicService.findAllOwners().stream()
533	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
534	            .count() + 1;
535	    }
