603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
606	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
607	        validateRequiredFields(ownerFieldsDto);
608	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
609	        if (registrationDate == null) {
610	            registrationDate = LocalDate.now();
611	        } else if (registrationDate.isAfter(LocalDate.now())) {
612	            throw new FutureRegistrationDateException(
613	                "registrationDate must not be later than the server date");
614	        }
615	        registrationDate = toBusinessDay(registrationDate);
616	        ownerFieldsDto.setRegistrationDate(registrationDate);
617	        rejectDailyOwnerLimit(registrationDate);
618	        rejectCityAtCapacity(ownerFieldsDto.getCity());
619	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
620	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
621	        ownerFieldsDto.setTelephone(normalizedTelephone);
622	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
623	        ownerFieldsDto.setEmail(normalizedEmail);
624	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
625	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
626	            : null;
627	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
628	        HttpHeaders headers = new HttpHeaders();
629	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
630	        owner.setCustomerCode(customerCode(
631	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
632	        owner.setHouseholdId(ownerHouseholdId);
633	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
634	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
635	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
636	        this.clinicService.saveOwner(owner);
637	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
638	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
639	            ownerMapper.membershipLevel(owner));
640	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
641	        headers.setLocation(UriComponentsBuilder.newInstance()
642	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
643	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
644	    }
