108	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
109	        if (hasEmail) {
110	            level++;
111	        }
112	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
113	        if (noNamesakes) {
114	            level++;
115	        }
116	        return Math.min(level, 3);
117	    }
