119	    /**
120	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
121	     * last two digits of the registrationDate year, e.g. {@code 'MEL-SMI-0007-M26'}.
122	     */
123	    default @Nullable String membershipNumber(@Nullable Owner owner) {
124	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
125	            return null;
126	        }
127	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
128	    }
129	
130	    /**
131	     * Returns the Luhn check digit (0-9) computed over the digits contained in the owner's
132	     * customerCode, or {@code null} when the owner or its customerCode is absent.
133	     */
134	    default @Nullable Integer checkDigit(@Nullable Owner owner) {
135	        if (owner == null || owner.getCustomerCode() == null) {
136	            return null;
137	        }
138	        String s = owner.getCustomerCode();
139	        int sum = 0;
140	        boolean dbl = true;
141	        for (int i = s.length() - 1; i >= 0; i--) {
142	            char c = s.charAt(i);
143	            if (c < '0' || c > '9') {
144	                continue;
145	            }
146	            int d = c - '0';
147	            if (dbl) {
148	                d *= 2;
149	                if (d > 9) {
150	                    d -= 9;
151	                }
152	            }
153	            sum += d;
154	            dbl = !dbl;
155	        }
156	        return (10 - (sum % 10)) % 10;
157	    }
158	
159	    /**
160	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
161	     */
162	    default @Nullable String displayName(@Nullable Owner owner) {
163	        if (owner == null) {
164	            return null;
165	        }
166	        return owner.getLastName() + ", " + owner.getFirstName();
167	    }
168	
169	    /**
170	     * Formats an owner's initials as the upper-cased first letters of firstName and
171	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
172	     */
173	    default @Nullable String initials(@Nullable Owner owner) {
174	        if (owner == null) {
175	            return null;
176	        }
177	        StringBuilder sb = new StringBuilder();
178	        String firstName = owner.getFirstName();
179	        if (firstName != null && !firstName.isEmpty()) {
180	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
181	        }
182	        String lastName = owner.getLastName();
183	        if (lastName != null && !lastName.isEmpty()) {
184	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
185	        }
186	        return sb.toString();
187	    }
