188	    /**
189	     * Normalizes a telephone on create into E.164 form. Spaces, dashes and brackets are stripped.
190	     * A leading {@code +} and its country code are kept as given; otherwise the country code
191	     * {@code +61} is assumed and a single leading {@code 0} is dropped from the national digits.
192	     * The result must carry 8 to 15 digits after the {@code +}. In addition, when the country code
193	     * is recognized the national number must have the exact length that code requires ({@code +61}
194	     * expects 9 national digits, {@code +1} expects 10). Returns the E.164 string to be stored and
195	     * returned.
196	     *
197	     * @param telephone the raw telephone as supplied by the caller
198	     * @return the normalized E.164 telephone (a {@code +} followed by 8 to 15 digits)
199	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
200	     *     national-number length is wrong for its country code
201	     */
202	    private static String normalizeTelephone(String telephone) {
203	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
204	        String e164;
205	        if (cleaned.startsWith("+")) {
206	            e164 = "+" + cleaned.substring(1);
207	        } else {
208	            String national = cleaned;
209	            if (national.startsWith("0")) {
210	                national = national.substring(1);
211	            }
212	            e164 = "+61" + national;
213	        }
214	        String digits = e164.substring(1);
215	        if (!digits.matches("\\d{8,15}")) {
216	            throw new InvalidTelephoneException(
217	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
218	        }
219	        if (digits.startsWith("61")) {
220	            requireNationalLength(digits.substring(2), 9, "+61");
221	        } else if (digits.startsWith("1")) {
222	            requireNationalLength(digits.substring(1), 10, "+1");
223	        }
224	        return e164;
225	    }
226	
227	    /**
228	     * Enforces that the national portion of an E.164 number has the exact number of digits its
229	     * country code requires.
230	     *
231	     * @param national the national-number digits (the part after the country code)
232	     * @param expected the exact national-number length the country code requires
233	     * @param countryCode the country code, for the error message
234	     * @throws InvalidTelephoneException if {@code national} does not have exactly {@code expected} digits
235	     */
236	    private static void requireNationalLength(String national, int expected, String countryCode) {
237	        if (national.length() != expected) {
238	            throw new InvalidTelephoneException(
239	                "Telephone with country code '" + countryCode + "' must have " + expected
240	                    + " national digits");
241	        }
242	    }
