263	    /**
264	     * Derives the single duplicate-detection key that consolidates the former separate telephone,
265	     * email and household checks. The key is {@code normalizedTelephone + '|' + email + '|' +
266	     * householdId}, where the email segment is the empty string when the owner has no email. Because
267	     * the telephone is part of the key, two owners that differ in any one segment (for example two
268	     * members of the same household with different telephones) produce different keys.
269	     *
270	     * @param normalizedTelephone the E.164 telephone of the owner
271	     * @param email the lower-cased email of the owner, may be {@code null}
272	     * @param householdId the stable household identifier of the owner, may be {@code null}
273	     * @return the derived identity key
274	     */
275	    private static String deriveIdentityKey(String normalizedTelephone, String email, String householdId) {
276	        return (normalizedTelephone == null ? "" : normalizedTelephone)
277	            + "|" + (email == null ? "" : email)
278	            + "|" + (householdId == null ? "" : householdId);
279	    }
