301	    /**
302	     * Normalizes a value for household comparison by trimming, collapsing every run of whitespace to
303	     * a single space and lower-casing, so the comparison is case-insensitive with collapsed whitespace.
304	     *
305	     * @param value the raw value, may be {@code null}
306	     * @return the normalized value ({@code ""} when {@code value} is {@code null})
307	     */
308	    private static String normalizeForHousehold(String value) {
309	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
310	    }
