391	    /**
392	     * The number of owners that may already exist for a business day before a create is flagged with
393	     * a bulk-signup warning. Once more than this many owners already carry the effective registration
394	     * date, the created owner's {@code bulkSignupWarning} is set to {@code true}.
395	     */
396	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
397	
398	    /**
399	     * Determines whether a create should be flagged with a bulk-signup warning, i.e. whether more than
400	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for the given business day,
401	     * counted by {@code registrationDate} equal to the effective (weekend rolled forward) registration
402	     * date of the owner being created. The count reflects the state before the new owner is persisted,
403	     * so it excludes the owner being created.
404	     *
405	     * @param registrationDate the effective business-day registration date of the owner being created
406	     * @return {@code true} when more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the date
407	     */
408	    private boolean bulkSignupWarning(LocalDate registrationDate) {
409	        long ownersToday = this.clinicService.findAllOwners().stream()
410	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
411	            .count();
412	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
413	    }
