518	     * Counts the members of the owner-to-be's household after this create, i.e. one more than the
519	     * number of existing owners already carrying the same {@code householdId}. A household identifier
520	     * is only assigned to owners who knowingly share a household via {@code sharesHousehold}; a solo
521	     * owner has no household identifier ({@code null}) and is therefore always a household of one. The
522	     * count includes the owner being created (hence the {@code + 1}).
523	     *
524	     * @param householdId the stable household identifier of the owner being created, or {@code null}
525	     *     when the owner does not share a household
526	     * @return the number of household members after this create (always at least 1)
527	     */
528	    private int householdSize(String householdId) {
529	        if (householdId == null) {
530	            return 1;
531	        }
532	        return (int) this.clinicService.findAllOwners().stream()
533	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
534	            .count() + 1;
535	    }
