538	     * Normalizes a name for case-insensitive comparison by trimming surrounding whitespace and
539	     * lower-casing.
540	     *
541	     * @param value the raw name, may be {@code null}
542	     * @return the normalized name ({@code ""} when {@code value} is {@code null})
543	     */
544	    private static String normalizeName(String value) {
545	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
