548	    /**
549	     * The fixed city-to-region table used to validate a postcode against its city
550	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD). A city not in this table has no known region and
551	     * therefore accepts any 4-digit postcode.
552	     */
553	    private static final java.util.Map<String, String> CITY_REGION = java.util.Map.of(
554	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
555	
556	    /**
557	     * The fixed region-to-postcode-range table: each region admits an inclusive 4-digit range
558	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
559	     */
560	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
561	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
562	
563	    /**
564	     * Validates an owner's optional postcode on create. A {@code null} or blank postcode is left
565	     * untouched (postcode is optional when absent). When present it must be exactly four digits and,
566	     * when the city maps to a known region, must fall within that region's inclusive range
567	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
568	     * postcode.
569	     *
570	     * @param city the city of the owner being created
571	     * @param postcode the raw postcode as supplied by the caller, may be {@code null}
572	     * @throws InvalidPostcodeException if a present postcode is not four digits or is out of range
573	     *     for the city's region
574	     */
575	    private static void validatePostcode(String city, String postcode) {
576	        if (postcode == null || postcode.isBlank()) {
577	            return;
578	        }
579	        if (!postcode.matches("\\d{4}")) {
580	            throw new InvalidPostcodeException("Postcode must be exactly 4 digits");
581	        }
582	        String region = CITY_REGION.get(city);
583	        int[] range = region == null ? null : REGION_POSTCODES.get(region);
584	        if (range != null) {
585	            int value = Integer.parseInt(postcode);
586	            if (value < range[0] || value > range[1]) {
587	                throw new InvalidPostcodeException(
588	                    "Postcode is out of range for the city's region");
589	            }
590	        }
591	    }
592	
593	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
594	    @Override
595	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
596	        Owner owner = this.clinicService.findOwnerById(ownerId);
597	        if (owner == null) {
598	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
599	        }
600	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
606	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
607	        validateRequiredFields(ownerFieldsDto);
608	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
609	        if (registrationDate == null) {
610	            registrationDate = LocalDate.now();
611	        } else if (registrationDate.isAfter(LocalDate.now())) {
612	            throw new FutureRegistrationDateException(
613	                "registrationDate must not be later than the server date");
614	        }
615	        registrationDate = toBusinessDay(registrationDate);
616	        ownerFieldsDto.setRegistrationDate(registrationDate);
617	        rejectDailyOwnerLimit(registrationDate);
618	        rejectCityAtCapacity(ownerFieldsDto.getCity());
619	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
620	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
621	        ownerFieldsDto.setTelephone(normalizedTelephone);
622	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
623	        ownerFieldsDto.setEmail(normalizedEmail);
624	        String ownerHouseholdId = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
625	            ? householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress())
626	            : null;
627	        rejectDuplicateIdentity(deriveIdentityKey(normalizedTelephone, normalizedEmail, ownerHouseholdId));
628	        HttpHeaders headers = new HttpHeaders();
629	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
630	        owner.setCustomerCode(customerCode(
631	            ownerFieldsDto.getPostcode(), normalizedTelephone, ownerFieldsDto.getLastName()));
632	        owner.setHouseholdId(ownerHouseholdId);
633	        owner.setHouseholdSize(householdSize(ownerHouseholdId));
634	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
635	        owner.setBulkSignupWarning(bulkSignupWarning(registrationDate));
636	        this.clinicService.saveOwner(owner);
637	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
638	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
639	            ownerMapper.membershipLevel(owner));
640	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
641	        headers.setLocation(UriComponentsBuilder.newInstance()
642	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
643	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
644	    }
645	
646	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
647	    @Override
648	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
649	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
650	        if (currentOwner == null) {
651	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
652	        }
653	        currentOwner.setAddress(ownerFieldsDto.getAddress());
654	        currentOwner.setCity(ownerFieldsDto.getCity());
655	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
656	        currentOwner.setLastName(ownerFieldsDto.getLastName());
657	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
658	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
659	        this.clinicService.saveOwner(currentOwner);
660	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
661	    }
662	
663	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
664	    @Transactional
665	    @Override
666	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
667	        Owner owner = this.clinicService.findOwnerById(ownerId);
668	        if (owner == null) {
669	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
670	        }
671	        this.clinicService.deleteOwner(owner);
672	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
673	    }
674	
675	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
676	    @Override
677	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
678	        Owner owner = this.clinicService.findOwnerById(ownerId);
679	        if (owner == null) {
680	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
681	        }
682	        HttpHeaders headers = new HttpHeaders();
683	        Pet pet = petMapper.toPet(petFieldsDto);
684	        owner.setId(ownerId);
685	        pet.setOwner(owner);
686	        pet.getType().setName(null);
687	        this.clinicService.savePet(pet);
688	        PetDto petDto = petMapper.toPetDto(pet);
689	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
690	            .buildAndExpand(pet.getId()).toUri());
691	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
692	    }
693	
694	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
695	    @Override
696	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
697	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
698	        if (currentOwner != null) {
699	            Pet currentPet = this.clinicService.findPetById(petId);
700	            if (currentPet != null) {
701	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
702	                currentPet.setName(petFieldsDto.getName());
703	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
704	                this.clinicService.savePet(currentPet);
705	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
706	            }
707	        }
708	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
709	    }
710	
711	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
712	    @Override
713	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
714	        HttpHeaders headers = new HttpHeaders();
715	        Visit visit = visitMapper.toVisit(visitFieldsDto);
716	        Pet pet = new Pet();
717	        pet.setId(petId);
718	        visit.setPet(pet);
719	        this.clinicService.saveVisit(visit);
720	        VisitDto visitDto = visitMapper.toVisitDto(visit);
721	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
722	            .buildAndExpand(visit.getId()).toUri());
723	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
724	    }
725	
726	
727	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
728	    @Override
729	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
730	        Owner owner = this.clinicService.findOwnerById(ownerId);
731	        if (owner != null) {
732	            Pet pet = owner.getPet(petId);
733	            if (pet != null) {
734	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
735	            }
736	        }
737	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
738	    }
739	}
